assert calculate_median_donation_per_donor([("Bob", 100)], [("Bob", 2)], []) == {"Bob": 50.0}

assert calculate_median_donation_per_donor([("Bob", 100)], [("Bob", 2)], [("Bob", 150, 3)]) == {"Bob": 50.0}

