assert calculate_median_donation_per_donor([], [], []) == {}

assert calculate_median_donation_per_donor([("Alice", 150), ("Bob", 100), ("Charlie", 200)], [("Alice", 3), ("Bob", 2), ("Charlie", 4)], [("Alice", 180, 4), ("Bob", 150, 3), ("Charlie", 240, 5)]) == {"Alice": 45.0, "Bob": 50.0, "Charlie": 48.0}

